import{e as t,ab as a,a1 as o,m as s,r as n,p as i}from"./chunks/framework.BGh0NSIy.js";const b=JSON.parse('{"title":"Monthly Updates [July]","description":"July 2025 updates","frontmatter":{"title":"Monthly Updates [July]","description":"July 2025 updates","date":"2025-07-01T00:00:00.000Z","next":false,"prev":false,"footer":true},"headers":[],"relativePath":"posts/july-2025.md","filePath":"posts/july-2025.md"}'),l={name:"posts/july-2025.md"};function d(h,e,p,f,m,g){const r=a("Post");return o(),s("div",null,[n(r,{authors:"nbats"}),e[0]||(e[0]=i('<div class="info custom-block"><p class="custom-block-title">INFO</p><p>These update threads only contain major updates. If you&#39;re interested in seeing all minor changes you can follow our <a href="https://github.com/fmhy/FMHYedit/commits/main" target="_blank" rel="noreferrer">Commits Page</a> on GitHub or <a href="https://redd.it/17f8msf" target="_blank" rel="noreferrer">Updates Channel</a> in Discord.</p></div><h1 id="wiki-updates" tabindex="-1">Wiki Updates <a class="header-anchor" href="#wiki-updates" aria-label="Permalink to &quot;Wiki Updates&quot;">​</a></h1><ul><li><p>Added <strong><a href="https://i.ibb.co/PZdY4rBZ/image.png" target="_blank" rel="noreferrer">Platform Icons</a></strong> to descriptions on the website. Note that more sections may get icons in the future where we feel necessary. TY to hugo for this.</p></li><li><p>Started a <strong><a href="https://docs.google.com/spreadsheets/d/1xZm5BcQTYJx8sfSuqHExHtIOPtSfod8beHKtYzp8DxE/" target="_blank" rel="noreferrer">YouTube Channel Spreadsheet</a></strong> with channels recommended by FMHY users. TY to zink for this.</p></li><li><p>Added a <strong><a href="https://fmhy.net/startpage" target="_blank" rel="noreferrer">Browser Startpage</a></strong> to our website. If there&#39;s anything you guys would like added to it, let us know. TY to tasky for this.</p></li><li><p>Added <a href="https://fmhy.net/gaming#tabletop-games" target="_blank" rel="noreferrer">Tabletop</a>, <a href="https://fmhy.net/gaming#chess" target="_blank" rel="noreferrer">Chess</a>, <a href="https://fmhy.net/gaming#card-games" target="_blank" rel="noreferrer">Card</a>, <a href="https://fmhy.net/educational#dungeons-dragons" target="_blank" rel="noreferrer">Dungeons &amp; Dragons</a>, and <a href="https://fmhy.net/gaming-tools#rpg-worldbuilding" target="_blank" rel="noreferrer">RPG Worldbuilding</a> sections.</p></li><li><p>Updated guides: <a href="https://fmhy.net/privacy#vpn-tools" target="_blank" rel="noreferrer">VPN Binding</a> / <a href="https://fmhy.net/system-tools#windows-isos" target="_blank" rel="noreferrer">Windows Debloat</a> / <a href="https://fmhy.net/mobile#revanced-tools" target="_blank" rel="noreferrer">ReVanced Obtainium</a> / <a href="https://fmhy.net/video#smart-tv-firestick" target="_blank" rel="noreferrer">webOS Homebrew</a>.</p></li><li><p>Cleaned up <a href="https://fmhy.net/audio#royalty-free-music" target="_blank" rel="noreferrer">Royalty-Free Music</a>, added labels, and moved it from storage to its own section. <a href="https://i.ibb.co/20Bb99zP/image.png" target="_blank" rel="noreferrer">Before vs. After</a>.</p></li><li><p>Cleaned up <a href="https://fmhy.net/image-tools#content-removers" target="_blank" rel="noreferrer">Content Removers</a>, merged both sections, and moved them out of storage. <a href="https://i.ibb.co/rnThdr5/Untitled.jpg" target="_blank" rel="noreferrer">Before vs. After</a>.</p></li><li><p>Cleaned up <a href="https://fmhy.net/file-tools#file-transfer" target="_blank" rel="noreferrer">File / P2P Transfer</a>; removed any that were unmaintained or had bad privacy policies. <a href="https://i.ibb.co/GfK168jD/Untitled.jpg" target="_blank" rel="noreferrer">Before vs. After</a>.</p></li><li><p>Cleaned up <a href="https://fmhy.net/developer-tools#regex-tools" target="_blank" rel="noreferrer">Regex Tools</a>, <a href="https://fmhy.net/developer-tools#map-creators-editors" target="_blank" rel="noreferrer">Map Creators / Editors</a>, and <a href="https://fmhy.net/gaming-tools#tabletop-tools" target="_blank" rel="noreferrer">Tabletop Tool</a> sections.</p></li><li><p>Moved <a href="https://fmhy.net/reading#browser-ebook-readers" target="_blank" rel="noreferrer">Browser Ebook Readers</a> + <a href="https://fmhy.net/developer-tools#game-assets" target="_blank" rel="noreferrer">Game Assets</a> out of storage into their own sections.</p></li><li><p>Split <a href="https://fmhy.net/misc#job-search-application" target="_blank" rel="noreferrer">Job Search / Application</a> sites into their own section under Career.</p></li></ul><hr><h1 id="stars-added-⭐" tabindex="-1">Stars Added ⭐ <a class="header-anchor" href="#stars-added-⭐" aria-label="Permalink to &quot;Stars Added ⭐&quot;">​</a></h1><ul><li><p>Starred <a href="https://fmhy.net/video#drives-directories" target="_blank" rel="noreferrer">Acer Movies</a> in Drives / Directories. Big library with single-click downloads.</p></li><li><p>Starred <a href="https://fmhy.net/gaming-tools#game-launchers" target="_blank" rel="noreferrer">Ascendara</a> in Game Launchers. Open-source, feature-rich game manager with easy in-app downloads.</p></li><li><p>Starred <a href="https://fmhy.net/ai#image-generation" target="_blank" rel="noreferrer">GPT1Image</a> in Image Generators. Free unlimited GPT-Image-1 images.</p></li><li><p>Starred <a href="https://fmhy.net/gaming#rom-sites" target="_blank" rel="noreferrer">Axekin</a> in ROM sites. Fast hosts, big library, and lots of platforms.</p></li><li><p>Starred <a href="https://nopaystation.com/" target="_blank" rel="noreferrer">NoPayStation</a> in Sony ROMs. One of the best sources for Sony platform ROMs.</p></li><li><p>Starred <a href="https://fmhy.net/mobile#android-file-tools" target="_blank" rel="noreferrer">1DM</a> in Android Download Managers as it <a href="https://i.ibb.co/zh2BKZ0z/image.png" target="_blank" rel="noreferrer">won in polls</a> and has features like split-file support.</p></li><li><p>Starred <a href="https://fmhy.net/mobile#youtube-music" target="_blank" rel="noreferrer">Metrolist</a> in Android YouTube Music players, as people feel this stands out the most of the Outertune forks.</p></li><li><p>Starred <a href="https://fmhy.net/mobile#apk-tools" target="_blank" rel="noreferrer">AntiSplit-M</a> in APK Tools. Easily merge split APK files.</p></li><li><p>Starred <a href="https://fmhy.net/audio#last-fm-tools" target="_blank" rel="noreferrer">bleh</a> in Last.fm Tools. Feature-rich customization script that makes the site look much better.</p></li><li><p>Starred <a href="https://fmhy.net/mobile#modded-apks" target="_blank" rel="noreferrer">PDALife</a> in Modded APKs. Easy download process, fast host, and good for modded games.</p></li><li><p>Starred <a href="https://fmhy.net/misc#tech-news" target="_blank" rel="noreferrer">GamersNexus</a> in Tech News. In-depth component reviews and news for PC building.</p></li><li><p>Starred <a href="https://fmhy.net/audio#concerts-live-shows" target="_blank" rel="noreferrer">bt.etree, MiroPPB (ASOT), and BBC Essential</a> in Concert / Live Shows.</p></li><li><p>Starred <a href="https://fmhy.net/reading#light-novels" target="_blank" rel="noreferrer">NovelFire</a> in Light Novels. Nice UI; allows login to rate and save progress.</p></li><li><p>Starred <a href="https://fmhy.net/ai#self-hosting-tools" target="_blank" rel="noreferrer">LM Studio</a> in AI Self-Hosting. Useful for running models locally; supports all GPUs or runs on CPU if needed.</p></li><li><p>Starred <a href="https://fmhy.net/privacy#vpn-tools" target="_blank" rel="noreferrer">Tailscale</a> in VPN Tools. Secure Network VPN that&#39;s easy to use and very <a href="https://i.ibb.co/ZRhQBNtX/image.png" target="_blank" rel="noreferrer">feature-rich</a>.</p></li><li><p>Starred <a href="https://fmhy.net/educational#med-school" target="_blank" rel="noreferrer">Stop The Bleed</a> in Med School. Free first aid video courses and resources.</p></li></ul><hr><h1 id="things-removed" tabindex="-1">Things Removed <a class="header-anchor" href="#things-removed" aria-label="Permalink to &quot;Things Removed&quot;">​</a></h1><ul><li><p>Unstarred G-MEH as it tends to have outdated plugins, disabled pages, and people feel there are better options.</p></li><li><p>Unstarred SystemRequirementsLab as people don&#39;t feel it&#39;s very useful anymore.</p></li><li><p>Unstarred Comfy Online as it has older / more limited models than other starred options.</p></li><li><p>Removed Awesome Piracy as it&#39;s no longer maintained very well. No disrespect intended - Awesome Piracy is older than FMHY and inspired us in a lot of ways early on; if it starts getting maintained better, we&#39;ll consider re-adding it.</p></li></ul>',9))])}const u=t(l,[["render",d]]);export{b as __pageData,u as default};
